// Fan guard / grill - an outer ring, a central hub and radial spokes. NOVEL general part.
//

od     = 53.3;
spokes = 8;
t      = 3.5;
hub_d  = 19.6;

$fn = 96;

ring_w = 4;

union() {
    difference() {
        cylinder(h = t, d = od);
        translate([0, 0, -1]) cylinder(h = t + 2, d = od - 2 * ring_w);
    }
    cylinder(h = t, d = hub_d);
    for (i = [0 : spokes - 1])
        rotate([0, 0, i * 360 / spokes]) translate([0, -1.5, 0]) cube([od / 2, 3, t]);
}

